class Solution {
public:
    int sumOddLengthSubarrays(vector<int>& arr) {
        int n = arr.size();
        int total = 0;
        for (int i = 0; i < n; i++) {
            int evenStarts = countParity(0, i, 0);
            int oddStarts  = countParity(0, i, 1);
            int evenEnds   = countParity(i, n - 1, 0);
            int oddEnds    = countParity(i, n - 1, 1);
            int cnt = evenStarts * evenEnds + oddStarts * oddEnds;
            total += arr[i] * cnt;
        }
        return total;
    }
private:
    int countParity(int a, int b, int r) {
        if (a > b) return 0;
        if (a % 2 != r) a++;
        if (a > b) return 0;
        return (b - a) / 2 + 1;
    }
};
